const now = new Date();
const today = now.toISOString().slice(0, 10);
const due = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
const stamp = Date.now();
const runId = `N8N-SELL-REAL-${stamp}`;
return [{
  json: {
    runId,
    company: 'Thái Duy Digital',
    transactionDate: today,
    validTill: due,
    deliveryDate: due,
    dueDate: due,
    customerName: `${runId} KH Đặc biệt & Space / Test`,
    disabledCustomerName: `${runId} Disabled Customer`,
    leadName: `${runId} Lead Đặc biệt`,
    salesPartnerName: `${runId} Sales Partner`,
    itemA: `${runId} Dịch vụ bán đặc biệt A`,
    itemB: `${runId} Service With Spaces B`,
    qtyA: 2,
    qtyB: 3,
    rateA: 150,
    rateB: 95,
    discountAmount: 10,
    accounts: {
      cash: '1110 - Cash - TDD',
      receivable: '1310 - Debtors - TDD',
      sales: '4110 - Sales - TDD'
    }
  }
}];

const ctx = $node['Build Real Sales Context'].json;
const docs = {
  customer: $node['Create Special Customer V2'].json.name,
  disabledCustomer: $node['Create Disabled Customer V2'].json.name,
  lead: $node['Create Lead V2'].json.name,
  itemA: $node['Create Sales Item A V2'].json.name,
  itemB: $node['Create Sales Item B V2'].json.name,
  opportunity: $node['Create Opportunity V2'].json.name,
  quotation: $node['Submit Quotation V2'].json.name,
  salesOrder: $node['Submit Sales Order V2'].json.name,
  salesInvoice: $node['Submit Sales Invoice Custom V2'].json.name,
  paymentEntry: $node['Submit Payment Entry Custom V2'].json.name
};
const invoice = $node['Submit Sales Invoice Custom V2'].json;
const payment = $node['Submit Payment Entry Custom V2'].json;
const salesOrder = $node['Get Sales Order By Custom DocType V2'].json;
const serialized = JSON.stringify({ docs, invoice: { name: invoice.name, grand_total: invoice.grand_total }, payment: { name: payment.name, paid_amount: payment.paid_amount } });
const patterns = [/api[_-]?key/i, /api[_-]?secret/i, /authorization/i, /token\s+[A-Za-z0-9]/i, /password/i];
const securityFindings = patterns.filter((pattern) => pattern.test(serialized)).map((pattern) => pattern.toString());
return [{ json: {
  runId: ctx.runId,
  status: securityFindings.length === 0 ? 'passed' : 'needs_review',
  customerSpecialChars: ctx.customerName,
  disabledCustomerDisabled: $node['Get Disabled Customer V2'].json.disabled,
  salesOrderDocTypeReadback: salesOrder.name,
  salesOrderGrandTotal: salesOrder.grand_total,
  salesInvoiceGrandTotal: invoice.grand_total,
  paymentReceivedAmount: payment.received_amount,
  docs,
  securityFindings,
  responsePolicy: 'Only document names, totals, and leak-scan status are returned. Credentials and raw upstream errors are not returned by this summary node.'
} }];
